import sys
import json
from pathlib import Path
from datetime import datetime

FACT_FIELD_MAP = {
    "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
    "classification date": ("fda_enforcement_reports", "center_classification_date"),
    "termination date": ("fda_enforcement_reports", "termination_date"),
}

def normalize_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val or val.upper() in ("N/A", "NA", "NONE", "UNKNOWN"):
        return None
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:8]}"
    if len(val) == 10 and val[4] == '-' and val[7] == '-':
        return val
    for fmt in ("%Y%m%d", "%Y-%m-%d", "%m/%d/%Y", "%m/%d/%y"):
        try:
            dt = datetime.strptime(val, fmt)
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            pass
    return val

def load_records(packet_dir):
    json_path = packet_dir / "fda_enforcement_reports.json"
    if not json_path.exists():
        return {}

    with open(json_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    if isinstance(data, dict) and "results" in data:
        results = data["results"]
    elif isinstance(data, list):
        results = data
    else:
        results = []

    records_by_entity = {}
    for r in results:
        rec_num = r.get("recall_number")
        if rec_num is not None:
            rec_num = str(rec_num).strip()
            records_by_entity.setdefault(rec_num, []).append(r)

    return records_by_entity

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = Path(sys.argv[1])
    manifest_path = Path(sys.argv[2])

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_schema = manifest.get("facts", {})

    records_by_entity = load_records(packet_dir)

    out = {}
    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        entity = entity.strip()
        facts = facts_schema.get(rule_id, [])

        pair_result = {}
        matching_records = records_by_entity.get(entity, [])

        for fact in facts:
            if fact not in FACT_FIELD_MAP:
                pair_result[fact] = "ABSENT"
                continue

            doc_name, field_name = FACT_FIELD_MAP[fact]
            values = set()

            for rec in matching_records:
                raw_val = rec.get(field_name)
                norm_val = normalize_date(raw_val)
                if norm_val is not None:
                    values.add(norm_val)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact] = [list(values)[0], doc_name]
            else:
                pair_result[fact] = "CONFLICT"

        out[pair] = pair_result

    print(json.dumps(out, indent=1))

if __name__ == "__main__":
    main()
