import json
import os
import sys

def format_date(val):
    if not val:
        return None
    val = str(val).strip()
    if not val:
        return None
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:]}"
    if len(val) == 10 and val[4] == '-' and val[7] == '-':
        return val
    return val

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load fda_enforcement_reports
    fda_file_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    records_by_recall_number = {}
    if os.path.exists(fda_file_path):
        with open(fda_file_path, "r", encoding="utf-8") as f:
            fda_data = json.load(f)
            if isinstance(fda_data, dict):
                results = fda_data.get("results", [])
            elif isinstance(fda_data, list):
                results = fda_data
            else:
                results = []

            for item in results:
                recall_num = item.get("recall_number")
                if recall_num:
                    records_by_recall_number.setdefault(recall_num, []).append(item)

    fact_field_mapping = {
        ("fda.classified_30d", "initiation date"): ("fda_enforcement_reports", "recall_initiation_date"),
        ("fda.classified_30d", "classification date"): ("fda_enforcement_reports", "center_classification_date"),
        ("fda.terminated_180d", "initiation date"): ("fda_enforcement_reports", "recall_initiation_date"),
        ("fda.terminated_180d", "termination date"): ("fda_enforcement_reports", "termination_date"),
    }

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        facts_list = facts_spec.get(rule_id, [])
        output[pair] = {}

        records = records_by_recall_number.get(entity, [])

        for fact_name in facts_list:
            mapping = fact_field_mapping.get((rule_id, fact_name))
