def format_date(val):
    if not val or not isinstance(val, str):
        return None
    val = val.strip()
    if not val:
        return None
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:]}"
    if len(val) == 10 and val[4] == '-' and val[7] == '-':
        return val
    return val

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load fda_enforcement_reports.json
    doc_name = "fda_enforcement_reports"
    json_path = os.path.join(packet_dir, f"{doc_name}.json")

    records_by_recall_number = {}
    if os.path.exists(json_path):
        with open(json_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
            results = data.get("results", [])
            for item in results:
                recall_num = item.get("recall_number")
                if recall_num:
                    records_by_recall_number.setdefault(recall_num, []).append(item)

    fact_field_map = {
        "initiation date": "recall_initiation_date",
        "classification date": "center_classification_date",
        "termination date": "termination_date"
    }

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        needed_facts = facts_spec.get(rule_id, [])

        pair_result = {}
        records = records_by_recall_number.get(entity, [])

        for fact_name in needed_facts:
            field_name = fact_field_map.get(fact_name)
            if not field_name:
                pair_result[fact_name] = "ABSENT"
                continue

            values = set()
            for rec in records:
                raw_val = rec.get(field_name)
                formatted_val = format_date(raw_val)
                if formatted_val:
                    values.add(formatted_val)

            if len(values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact_name] = [list(values)[0], doc_name]
            else:
                pair_result[fact_name] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=1))

if __name__ == "__main__":
    main()

