import json
import os
import sys

FACT_MAP = {
    "initiation date": ("fda_enforcement_reports", "recall_initiation_date", "date"),
    "classification date": ("fda_enforcement_reports", "center_classification_date", "date"),
    "termination date": ("fda_enforcement_reports", "termination_date", "date"),
}

def format_date(val):
    val = str(val).strip()
    if not val:
        return None
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:8]}"
    return val

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load fda_enforcement_reports.json
    reports_file = os.path.join(packet_dir, "fda_enforcement_reports.json")
    records_by_recall = {}
    if os.path.exists(reports_file):
        with open(reports_file, "r", encoding="utf-8") as f:
            data = json.load(f)
            results = data.get("results", [])
            for item in results:
                recall_num = item.get("recall_number")
                if recall_num:
                    records_by_recall.setdefault(recall_num, []).append(item)

    out = {}
    pairs = manifest.get("pairs", [])
    facts_def = manifest.get("facts", {})

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        facts_list = facts_def.get(rule_id, [])
        out[pair] = {}

        matching_records = records_by_recall.get(entity, [])

        for fact in facts_list:
            if fact not in FACT_MAP:
                out[pair][fact] = "ABSENT"
                continue

            doc_name, field_name, val_type = FACT_MAP[fact]
            vals = []
            for rec in matching_records:
                raw_val = rec.get(field_name)
                if raw_val is not None:
                    if val_type == "date":
                        formatted = format_date(raw_val)
                        if formatted:
                            vals.append(formatted)
                    else:
                        cleaned = str(raw_val).strip()
                        if cleaned:
                            vals.append(cleaned)

            unique_vals = list(dict.fromkeys(vals))
            if not unique_vals:
                out[pair][fact] = "ABSENT"
            elif len(unique_vals) > 1:
                out[pair][fact] = "CONFLICT"
            else:
                out[pair][fact] = [unique_vals[0], doc_name]

    print(json.dumps(out, indent=2))

if __name__ == "__main__":
    main()
